// ===== NODE "Dashboard" – TỰ NHẬN DIỆN CỘT, KHÔNG PHỤ THUỘC TÊN CỘT =====
// Đổi file Excel khác (cột khác) vẫn chạy được. Muốn chỉ định thủ công thì điền ở node "Cài đặt".

const rows = $input.all().map(i => i.json);
if (!rows.length) throw new Error('Không có dữ liệu từ node Excel');

// ---- 1. Đọc cài đặt (nếu có) ----
let cfg = {};
try { cfg = $('Cài đặt').first().json; } catch (e) {}
const list = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
const boQua = list(cfg.cot_bo_qua);

// ---- 2. Hàm tiện ích ----
const toNum = v => {
  if (typeof v === 'number') return v;
  if (v === null || v === undefined || v === '') return null;
  let s = String(v).replace(/[\s₫đ%$]|VND/gi, '');
  if (!/^-?[\d.,]+$/.test(s)) return null;
  if ((s.match(/\./g) || []).length > 1) s = s.replace(/\./g, '');        // 1.200.000
  if ((s.match(/,/g) || []).length > 1) s = s.replace(/,/g, '');
  s = s.replace(',', '.');
  const n = Number(s);
  return isNaN(n) ? null : n;
};
const toPeriod = (v, colName) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' && v > 20000 && v < 80000) {          // số serial ngày của Excel
    const d = new Date(Math.round((v - 25569) * 86400000));
    return d.toISOString().slice(0, 7);
  }
  const s = String(v);
  let m = s.match(/^(\d{4})[-/.](\d{1,2})/);                         // 2024-01 / 2024-01-15
  if (m) return `${m[1]}-${m[2].padStart(2, '0')}`;
  m = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);               // 15/01/2024
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}`;
  m = s.match(/^(\d{1,2})[-/.](\d{4})$/);                            // 01/2024
  if (m) return `${m[2]}-${m[1].padStart(2, '0')}`;
  if (/^\d{4}$/.test(s) && /nam|year/i.test(colName)) return s;
  return null;
};
const round = n => Math.round(n * 100) / 100;

// ---- 3. Nhận diện loại cột ----
const cols = [...new Set(rows.flatMap(r => Object.keys(r)))].filter(c => !boQua.includes(c));
const idName = /(^|_|\s)(id|key|code|sku|ma|mã|stt|index|phone|sdt|email)($|_|\s)/i;
const dateName = /date|ngay|ngày|thang|tháng|month|time|thoi_gian|thời gian|year|nam|năm|period|ky|kỳ/i;
const info = {};
for (const c of cols) {
  const vals = rows.map(r => r[c]).filter(v => v !== null && v !== undefined && v !== '');
  const uniq = new Set(vals.map(String)).size;
  const nums = vals.map(toNum).filter(v => v !== null);
  const periods = vals.map(v => toPeriod(v, c)).filter(Boolean);
  let type;
  if (!vals.length) type = 'trống';
  else if (dateName.test(c) && periods.length / vals.length > 0.8) type = 'thời gian';
  else if (!dateName.test(c) && typeof vals[0] === 'string' && periods.length / vals.length > 0.9) type = 'thời gian';
  else if (nums.length / vals.length > 0.9) {
    if (idName.test(c) && uniq > 30) type = 'mã/ID';
    else if (uniq <= 12 && idName.test(c)) type = 'nhóm';
    else if (uniq <= 5 && nums.every(Number.isInteger) && !/qty|so_luong|số lượng|quantity|don|đơn/i.test(c)) type = 'nhóm';
    else if (uniq / vals.length > 0.95 && vals.length > 50 && Number.isInteger(nums[0]) && nums[0] > 1e6) type = 'mã/ID';
    else type = 'số';
  }
  else if (uniq <= Math.max(50, rows.length * 0.05)) type = 'nhóm';
  else type = 'văn bản';
  info[c] = { type, so_gia_tri_khac_nhau: uniq };
}
// Cho phép ép kiểu bằng cài đặt
if (cfg.cot_thoi_gian && info[cfg.cot_thoi_gian]) info[cfg.cot_thoi_gian].type = 'thời gian';
if (cfg.cot_gia_tri && info[cfg.cot_gia_tri]) info[cfg.cot_gia_tri].type = 'số';
list(cfg.cot_nhom).forEach(c => info[c] && (info[c].type = 'nhóm'));

const measures = cols.filter(c => info[c].type === 'số');
const dims = cols.filter(c => info[c].type === 'nhóm')
  .sort((a, b) => info[a].so_gia_tri_khac_nhau - info[b].so_gia_tri_khac_nhau);
const timeCol = cols.find(c => info[c].type === 'thời gian');
const moneyName = /doanh|revenue|sales|value|amount|gia_tri|giá trị|tien|tiền|thu|gmv|profit|loi_nhuan/i;

// Chỉ số chính
const sums = {};
measures.forEach(m => sums[m] = rows.reduce((s, r) => s + (toNum(r[m]) || 0), 0));
const mainMeasure = (cfg.cot_gia_tri && measures.includes(cfg.cot_gia_tri)) ? cfg.cot_gia_tri
  : (measures.find(m => moneyName.test(m)) || measures.sort((a, b) => sums[b] - sums[a])[0]);

// ---- 4. Tính toán dashboard ----
const MAX_MEASURES = 8, MAX_DIMS = 6, TOP = 10;
const useMeasures = [mainMeasure, ...measures.filter(m => m !== mainMeasure)].filter(Boolean).slice(0, MAX_MEASURES);

const chi_so_tong = {};
useMeasures.forEach(m => {
  const v = rows.map(r => toNum(r[m])).filter(x => x !== null);
  chi_so_tong[m] = { tong: round(sums[m]), trung_binh: round(sums[m] / (v.length || 1)),
    nho_nhat: Math.min(...v), lon_nhat: Math.max(...v) };
});

const groupBy = (col, keyFn = r => r[col]) => {
  const g = {};
  rows.forEach(r => {
    const k = keyFn(r); if (k === null || k === undefined || k === '') return;
    g[k] = g[k] || { so_dong: 0 };
    g[k].so_dong++;
    useMeasures.forEach(m => g[k][m] = (g[k][m] || 0) + (toNum(r[m]) || 0));
  });
  return g;
};

const theo_nhom = {};
dims.slice(0, MAX_DIMS).forEach(d => {
  const g = groupBy(d);
  const total = mainMeasure ? sums[mainMeasure] : rows.length;
  theo_nhom[d] = Object.entries(g)
    .map(([k, v]) => ({ [d]: k, ...Object.fromEntries(Object.entries(v).map(([a, b]) => [a, round(b)])),
      ti_trong_pct: round(100 * (mainMeasure ? v[mainMeasure] : v.so_dong) / (total || 1)) }))
    .sort((a, b) => (mainMeasure ? b[mainMeasure] - a[mainMeasure] : b.so_dong - a.so_dong))
    .slice(0, TOP);
});

let xu_huong = null, bien_dong = null;
if (timeCol) {
  const g = groupBy(timeCol, r => toPeriod(r[timeCol], timeCol));
  xu_huong = Object.keys(g).sort().map(k => ({ ky: k, ...Object.fromEntries(Object.entries(g[k]).map(([a, b]) => [a, round(b)])) }));
  if (xu_huong.length >= 2) {
    const last = xu_huong[xu_huong.length - 1], prev = xu_huong[xu_huong.length - 2];
    bien_dong = { ky_moi_nhat: last.ky, ky_truoc: prev.ky };
    useMeasures.forEach(m => bien_dong[m + '_thay_doi_pct'] = prev[m] ? round(100 * (last[m] - prev[m]) / prev[m]) : null);
  }
}

// ---- 5. Biểu đồ (QuickChart) ----
const chartUrl = cfgChart => 'https://quickchart.io/chart?w=700&h=380&c=' + encodeURIComponent(JSON.stringify(cfgChart));
const bieu_do = [];
if (xu_huong && mainMeasure) {
  const s = xu_huong.slice(-24);
  bieu_do.push({ ten: `Xu hướng ${mainMeasure} theo ${timeCol}`, url: chartUrl({ type: 'line',
    data: { labels: s.map(x => x.ky), datasets: [{ label: mainMeasure, data: s.map(x => x[mainMeasure]), fill: false }] } }) });
}
dims.slice(0, 3).forEach(d => {
  const s = theo_nhom[d];
  bieu_do.push({ ten: `${mainMeasure || 'Số dòng'} theo ${d}`, url: chartUrl({ type: s.length <= 6 ? 'doughnut' : 'bar',
    data: { labels: s.map(x => x[d]), datasets: [{ label: mainMeasure || 'so_dong', data: s.map(x => x[mainMeasure || 'so_dong']) }] } }) });
});

// ---- 6. Bản tóm tắt ngắn gọn cho AI (giúp AI chạy nhanh, ít bị quá tải) ----
const fmt = n => (n === null || n === undefined) ? '-' : Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });
const L = [];
L.push(`Dữ liệu: ${rows.length} dòng. Chỉ số chính: ${mainMeasure || 'số dòng'}. Cột thời gian: ${timeCol || 'không có'}.`);
L.push('TỔNG: ' + useMeasures.map(m => `${m}=${fmt(chi_so_tong[m].tong)}`).join('; '));
if (bien_dong) L.push(`BIẾN ĐỘNG ${bien_dong.ky_moi_nhat} so với ${bien_dong.ky_truoc}: ` +
  useMeasures.map(m => `${m} ${bien_dong[m + '_thay_doi_pct'] > 0 ? '+' : ''}${fmt(bien_dong[m + '_thay_doi_pct'])}%`).join('; '));
dims.slice(0, MAX_DIMS).forEach(d => {
  L.push(`THEO ${d} (top 5): ` + theo_nhom[d].slice(0, 5).map(g =>
    `${g[d]} [` + useMeasures.slice(0, 5).map(m => `${m}=${fmt(g[m])}`).join(', ') + `, tỷ trọng ${g.ti_trong_pct}%]`).join(' | '));
});
if (xu_huong && mainMeasure) L.push(`XU HƯỚNG ${mainMeasure} 12 kỳ gần nhất: ` +
  xu_huong.slice(-12).map(x => `${x.ky}: ${fmt(x[mainMeasure])}`).join(', '));
const tom_tat_cho_AI = L.join('\n');

// ---- 7. Kết quả ----
return [{ json: {
  tong_quan: { so_dong: rows.length, so_cot: cols.length, chi_so_chinh: mainMeasure || null,
    cot_thoi_gian: timeCol || null, cot_so: useMeasures, cot_nhom: dims.slice(0, MAX_DIMS),
    cot_bo_qua: cols.filter(c => ['mã/ID', 'văn bản', 'trống'].includes(info[c].type)) },
  chi_so_tong, bien_dong, theo_nhom,
  xu_huong: xu_huong ? xu_huong.slice(-12) : null,
  bieu_do,
  tom_tat_cho_AI,
  cau_truc_cot: info
} }];

